// Synthetic encoder delivery fixtures. Each contains 1025 source samples and
// two priming AUs. PCM(c,i) = ((i % 67) - 33) * (c + 1) * 113.
// Dynamic sources use c=13..16; positions and exact reference are in regression.cpp.
// Base64 keeps the deterministic test data compact; no codec is linked to tests.
#pragma once
#include <cstdint>
#include <vector>
inline std::vector<uint8_t> profileBytes(const char *text) {
  std::vector<uint8_t> bytes;
  uint32_t pending = 0;
  unsigned bits = 0;
  for (const char *p = text; *p && *p != '='; ++p) {
    unsigned v = *p >= 'A' && *p <= 'Z' ? unsigned(*p-'A') :
                 *p >= 'a' && *p <= 'z' ? unsigned(*p-'a'+26) :
                 *p >= '0' && *p <= '9' ? unsigned(*p-'0'+52) :
                 *p == '+' ? 62u : 63u;
    pending = (pending << 6) | v;
    bits += 6;
    if (bits >= 8) { bits -= 8; bytes.push_back(uint8_t(pending >> bits)); }
  }
  return bytes;
}
